dtsPropsFor.StudioShell:
sidebarSlot: React.ReactNode;
mobileNavSlot: React.ReactNode;
topBarSlot: React.ReactNode;
children: React.ReactNode;

dtsPropsFor.StudioSidebar:
/** Presentation-only shim over the real Binding Shell (components/studio/StudioSidebar.jsx), which normally wires next/link and usePathname(). Here InternalLinkComponent is fixed to a plain "a" and pathname is an explicit prop. economySlot renders a labeled placeholder, not the live coin-balance widget (that widget reads Chassis-owned account context, out of sync scope). */
user?: { email?: string };
pathname?: string;

dtsPropsFor.StudioTopBar:
/** Presentation-only shim over components/studio/StudioTopBar.jsx. notifications render from a local demo-state module (studioTopBarNotifications.mock.js), the same fixture data the real wrapper's own demo state uses. */
user?: { email?: string };
onOpenMenu?: () => void;

dtsPropsFor.StudioMobileNav:
/** Presentation-only shim over components/studio/StudioMobileNav.jsx, pathname explicit instead of usePathname(). drawerEconomySlot renders a labeled placeholder (see StudioSidebar). */
user?: { email?: string };
open: boolean;
onCloseMenu?: () => void;
pathname?: string;

dtsPropsFor.Editor:
/** Advanced editor page View (docs/plans/ED1B-EDITOR-PAGE-SPEC.md, ED1C revision, contract 4.0.0). Composition top to bottom: back link -> hero slot -> section boxes (one open at a time) -> sticky rail (desktop) or bottom bar + sheet (mobile) -> overlays. Never imports Next.js or a Creation client. */
groups: Array<{
  id: string;
  label: string;
  sections: Array<{ id: string; label: string; icon?: React.ComponentType<{ size?: number }> }>;
}>;
openSectionId: string | null;
onOpenSection: (sectionId: string | null) => void;
sectionMarks?: Record<string, "dirty" | "saved">;
isDirty: boolean;
saveStatus: "idle" | "saving" | "saved" | "error";
saveErrorCopy?: string;
onSave: (() => void) | null;
onDiscard: (() => void) | null;
onOpenSwitcher: (() => void) | null;
sectionNodes: Record<string, React.ReactNode>;
sectionLeads?: Record<string, React.ReactNode>;
sectionBadges?: Record<string, React.ReactNode>;
sectionSeats?: Record<string, React.ReactNode>;
backLabel: string;
onBack: () => void;
hero: React.ReactNode;
featuredImagePicker?: React.ReactNode;
creationPicker?: React.ReactNode;
loadError: { message?: string } | null;
onRetryLoad?: () => void;
onOpenPickerFromError?: () => void;
isLoading?: boolean;
mobileNavOpen: boolean;
onToggleMobileNav: () => void;
harnessSlot?: React.ReactNode;

dtsPropsFor.KitFormField:
/** Contract 1.1.0. Four slots plus the input: label, input bed, helper line, error line, optional counter; an optional fold turns the field into a disclosure header over a field group. */
label: string;
value: string;
placeholder?: string;
helper?: string;
error?: string;
success?: string;
maxLength?: number | null;
count?: number | null;
isFolded?: boolean;
onToggleFold?: (() => void) | null;
children?: React.ReactNode;
isDisabled: boolean;
type?: "text" | "search" | "email" | "password" | "number";
variant?: "text" | "textarea" | "select" | "number";
mono?: boolean;
startExpanded?: boolean;
onSelect?: ((value: string) => void) | null;
onChange: ((value: string) => void) | null;
/** "select" variant only: passed through to KitDropdown unchanged. */
options?: Array<{ value: string; label: string; count?: number | null; description?: string; tooltip?: string; isDisabled?: boolean }>;

dtsPropsFor.KitDropdown:
/** Contract 1.1.0. One trigger opening one options panel: popover at 700px+, bottom-docked sheet under 700px. Each option: { value: string; label: string; count?: number | null; description?: string; tooltip?: string; isDisabled?: boolean }. */
label: string;
options: Array<{
  value: string;
  label: string;
  count?: number | null;
  description?: string;
  tooltip?: string;
  isDisabled?: boolean;
}>;
selectedValues: string[];
isMultiSelect: boolean;
isDisabled: boolean;
onToggleOption: ((value: string) => void) | null;
ariaLabel?: string | null;

dtsPropsFor.KitModalFrame:
/** Presentation-only wrapper over the ruled panel anatomy (contract 1.1.0) on top of ModalShell's behavioral primitive. No isOpen prop: renders when mounted. */
children: React.ReactNode;
onClose: (() => void) | null;
closeOnBackdrop?: boolean;
closeOnEscape?: boolean;
variant?: "modal" | "sheet" | "viewer";
panelClassName?: string;
ariaLabelledBy?: string;
ariaDescribedBy?: string;
ariaLabel?: string;

dtsPropsFor.KitBadge:
/** Contract 1.0.0. Non-interactive label; a clickable badge is a chip (KitFilterChip), not a badge. */
label: string;
variant: "canon" | "status" | "meta";
surface: "canvas" | "art";

dtsPropsFor.KitFilterChip:
/** Contract 1.0.0. */
label: string;
count: number | null;
isSelected: boolean;
variant: "default" | "sort" | "toggle" | "dropdown";
isDisabled: boolean;
onToggle: (() => void) | null;

dtsPropsFor.TextField:
/** Field grammar primitive (components/studio/my-creations/edit/sections/SharedFields.jsx), the ED1E label-row + bed + helper anatomy. */
label: string;
value?: string;
onChange?: (value: string) => void;
placeholder?: string;
maxLength?: number;
helperText?: string;
disabled?: boolean;

dtsPropsFor.SelectField:
/** Field grammar primitive; delegates to KitFormField variant="select" (which composes KitDropdown). options accepts plain strings or {value, label} pairs. */
label: string;
value?: string;
onChange?: (value: string) => void;
options?: (string | { value: string; label: string })[];
placeholder?: string;
helperText?: string;
disabled?: boolean;

dtsPropsFor.NumberField:
/** Field grammar primitive. No character counter (numeric values carry no length budget). */
label: string;
value?: string;
onChange?: (value: string) => void;
placeholder?: string;
min?: number;
max?: number;
step?: number;
helperText?: string;
disabled?: boolean;

dtsPropsFor.TextAreaField:
/** Field grammar primitive. Folding long-form field: rests collapsed at one line, expands on focus and stays expanded once touched. */
label: string;
value?: string;
onChange?: (value: string) => void;
placeholder?: string;
maxLength?: number;
helperText?: string;
disabled?: boolean;
mono?: boolean;

dtsPropsFor.ReadOnlyField:
/** Field grammar primitive. No bed: a bed means editable, absence of a bed means read-only. */
label: string;
value?: string;

dtsPropsFor.SectionTitle:
/** Field grammar primitive: eyebrow + title + body stack. Suppressed entirely inside the v2 Editor's section boxes (EditorSectionChromeContext), which render their own header. */
eyebrow: string;
title: string;
body: string;

dtsPropsFor.ActionPanel:
/** Field grammar primitive: a quiet callout panel with one secondary action, default disabled (honest stub pattern for not-yet-wired actions). */
title: string;
body: string;
button: string;
onClick?: () => void;
disabled?: boolean;

dtsPropsFor.ModalShell:
/** Shared floating-modal behavioral primitive (components/ui/ModalShell.jsx): fixed overlay, scrim, blur, backdrop dismiss, Escape, body-scroll lock. KitModalFrame is the ruled panel anatomy built on top of this. */
children: React.ReactNode;
onClose?: () => void;
closeOnBackdrop?: boolean;
closeOnEscape?: boolean;
className?: string;
veilClassName?: string;
panelClassName?: string;
ariaLabelledBy?: string;
ariaDescribedBy?: string;
